import type { TransitStop } from '../types/commute'

// Generated by scripts/fetch-stops.mjs (npm run stops) from OpenStreetMap data.
export async function fetchMadridTransitStops(): Promise<TransitStop[]> {
  try {
    const response = await fetch(`${import.meta.env.BASE_URL}madrid-stops.json`)
    if (!response.ok) {
      return []
    }
    return (await response.json()) as TransitStop[]
  } catch {
    return []
  }
}
